const VERSION='ember-vault-complete-'+(self.EMBER_RELEASE_ID||'dev-20261111b'),CACHE=VERSION+'-core',PACK=VERSION+'-pack';let manifest=null;const BASE=self.EMBER_ASSET_BASE||new URL('./',self.location.href),asset=p=>new URL(p,BASE).href;
const paths=async()=>{if(manifest)return manifest;const saved=await(await caches.open(CACHE)).match(asset('./sw-assets.json'));if(saved)return manifest=await saved.json();const response=await fetch(asset('./sw-assets.json'),{cache:'no-store'});if(!response.ok)throw Error('Release manifest unavailable');const data=await response.json();if(self.EMBER_RELEASE_ID&&data.releaseId!==self.EMBER_RELEASE_ID)throw Error('Release changed during installation');return manifest=data;};
async function verifiedFetch(path,data){
 const url=asset(path),expected=data.integrity[path];
 async function matches(response){if(!response.ok)return false;if(!expected)return true;const hash=await crypto.subtle.digest('SHA-256',await response.clone().arrayBuffer());return [...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('')===expected;}
 let response=await fetch(url,{cache:'force-cache'});if(!await matches(response))response=await fetch(url,{cache:'reload'});if(!await matches(response))throw Error('Release integrity mismatch: '+path);return response;
}
self.addEventListener('install',event=>event.waitUntil((async()=>{const data=await paths(),cache=await caches.open(CACHE);await Promise.all(data.core.map(async p=>cache.put(asset(p),await verifiedFetch(p,data))));await cache.put(asset('./sw-assets.json'),new Response(JSON.stringify(data),{headers:{'Content-Type':'application/json'}}));})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('ember-vault-complete-')&&![CACHE,PACK].includes(key))await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;event.respondWith((async()=>{const cached=await caches.match(event.request,{ignoreSearch:true});if(cached)return cached;try{const r=await fetch(event.request);if(r.ok){const c=await caches.open(PACK);await c.put(event.request,r.clone());}return r;}catch{if(event.request.mode==='navigate'){if(!u.pathname.startsWith(BASE.pathname))return Response.redirect(asset('./index.html'),302);return await caches.match(asset('./index.html'));}if(event.request.destination==='image')return await caches.match(asset('./assets/library-stage-v5.webp'));return new Response('Offline resource unavailable',{status:503});}})());});
self.addEventListener('message',event=>{if(event.data?.type==='skip-waiting'){event.waitUntil(self.skipWaiting());return;}if(event.data?.type!=='offline-pack')return;event.waitUntil((async()=>{const send=data=>event.source?.postMessage(data);try{const data=await paths(),cache=await caches.open(PACK);for(let i=0;i<data.pack.length;i++){const url=asset(data.pack[i]);if(!await caches.match(url,{ignoreSearch:true}))await cache.put(url,await verifiedFetch(data.pack[i],data));send({type:'offline-progress',done:i+1,total:data.pack.length});}send({type:'offline-complete'});}catch(e){send({type:'offline-error'});}})());});
